const now = new Date();
const arabicMonths = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
const arabicDays = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
function toArabicNumerals(num) {
  const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  return num.toString().split('').map(d => arabicNumerals[parseInt(d)] || d).join('');
}
const dateArabic = `${arabicDays[now.getDay()]}، ${toArabicNumerals(now.getDate())} ${arabicMonths[now.getMonth()]} ${toArabicNumerals(now.getFullYear())}`;
return { json: { date_arabic: dateArabic, date_english: now.toISOString().split('T')[0] } };

// Get all items from aggregated SERP results
const allItems = $input.first().json.data || $input.all();

let uaeNews = [];
let gccNews = [];
let intlNews = [];
let orgNews = [];
let allSources = [];
let sourceIndex = 1;

// Process each SERP result
const items = Array.isArray(allItems) ? allItems : [allItems];
for (const item of items) {
  const data = item.json || item;
  const query = data.search_parameters?.q || '';

  // Extract news results
  const newsResults = data.news_results || [];
  const news = newsResults.slice(0, 10).map(n => {
    const sourceName = n.source?.name || n.source || 'Unknown';
    const link = n.link || '';
    const idx = sourceIndex++;
    allSources.push({ index: idx, name: sourceName, url: link, title: n.title });
    return {
      title: n.title,
      source: sourceName,
      snippet: n.snippet || '',
      link: link,
      citation_index: idx
    };
  });

  // Categorize based on search query
  if (query.includes('UAE') || query.includes('Dubai')) {
    uaeNews = news;
  } else if (query.includes('Saudi') || query.includes('Kuwait')) {
    gccNews = news;
  } else if (query.includes('international') || query.includes('organized crime')) {
    intlNews = news;
  } else if (query.includes('INTERPOL') || query.includes('FBI')) {
    // Organizations search uses organic_results
    const orgResults = data.organic_results || [];
    orgNews = orgResults.slice(0, 10).map(n => {
      const sourceName = n.source?.name || n.source || 'Organization';
      const link = n.link || '';
      const idx = sourceIndex++;
      allSources.push({ index: idx, name: sourceName, url: link, title: n.title });
      return {
        title: n.title,
        source: sourceName,
        snippet: n.snippet || '',
        link: link,
        citation_index: idx
      };
    });
  }
}

return {
  json: {
    uae_news: uaeNews,
    gcc_news: gccNews,
    international_news: intlNews,
    org_news: orgNews,
    all_sources: allSources,
    total: uaeNews.length + gccNews.length + intlNews.length + orgNews.length
  }
};

var rawAnalysis = $json.choices && $json.choices[0] && $json.choices[0].message ? $json.choices[0].message.content : 'لا تتوفر بيانات';

// Get all sources from Combine News node
var allSources = [];
try {
  allSources = $('Combine News').item.json.all_sources || [];
} catch (e) {
  allSources = [];
}

// Build source lookup map by index
var sourceMap = {};
for (var s = 0; s < allSources.length; s++) {
  var src = allSources[s];
  sourceMap[src.index] = { name: src.name, url: src.url, title: src.title };
}

function cleanMetadata(text) {
  var patterns = ['كلمة', 'words', 'word', 'حرف', 'characters'];
  var result = text;
  for (var p = 0; p < patterns.length; p++) {
    var i = 0;
    while (i < result.length) {
      var openParen = result.indexOf('(', i);
      if (openParen === -1) break;
      var closeParen = result.indexOf(')', openParen);
      if (closeParen === -1) break;
      var inside = result.substring(openParen + 1, closeParen);
      if (inside.indexOf(patterns[p]) !== -1 && inside.length < 30) {
        result = result.substring(0, openParen) + result.substring(closeParen + 1);
      } else {
        i = openParen + 1;
      }
    }
  }
  return result.trim();
}

function getSourceName(url) {
  try {
    var domain = url.split('//')[1];
    if (!domain) return 'مصدر';
    domain = domain.split('/')[0].split('?')[0];
    domain = domain.replace('www.', '');
    var parts = domain.split('.');
    var name = parts.length >= 2 ? parts[parts.length - 2] : parts[0];
    name = name.charAt(0).toUpperCase() + name.slice(1);
    return name;
  } catch (e) { return 'مصدر'; }
}

const analysis = cleanMetadata(rawAnalysis);
const now = new Date();
const arabicMonths = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
const arabicDays = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
function toArabicNum(n) { return n.toString().split('').map(function(d) { return ['٠','١','٢','٣','٤','٥','٦','٧','٨','٩'][parseInt(d)] || d; }).join(''); }
const dateArabic = arabicDays[now.getDay()] + '، ' + toArabicNum(now.getDate()) + ' ' + arabicMonths[now.getMonth()] + ' ' + toArabicNum(now.getFullYear()) + 'م';
const dateEnglish = now.toISOString().split('T')[0];
const reportTitle = 'التقرير اليومي للرصد الجنائي - ' + dateArabic;

// Track which citations are used in the text
var usedCitations = {};

function addInlineCitations(text, srcMap) {
  var result = text;
  var citationPattern = /\[(\d+)\]/g;
  var match;
  var replacements = [];

  while ((match = citationPattern.exec(text)) !== null) {
    var citNum = parseInt(match[1]);
    usedCitations[citNum] = true;
    replacements.push({ num: citNum, start: match.index, end: match.index + match[0].length });
  }

  replacements.sort(function(a, b) { return b.start - a.start; });

  for (var r = 0; r < replacements.length; r++) {
    var rep = replacements[r];
    var src = srcMap[rep.num];
    var link;
    if (src && src.url) {
      var tooltip = src.name + ': ' + (src.title || '').substring(0, 100);
      link = '<a href="' + src.url + '" target="_blank" class="cite-link" title="' + tooltip.replace(/"/g, '&quot;') + '">[' + rep.num + ']</a>';
    } else {
      link = '<span class="cite-link">[' + rep.num + ']</span>';
    }
    result = result.substring(0, rep.start) + link + result.substring(rep.end);
  }

  return result;
}

function formatLine(line, srcMap) {
  line = addInlineCitations(line, srcMap);
  var parts = line.split('**');
  var result = '';
  for (var j = 0; j < parts.length; j++) {
    if (j % 2 === 1) {
      result += '<strong>' + parts[j] + '</strong>';
    } else {
      result += parts[j];
    }
  }
  return result;
}

function formatContent(text, srcMap) {
  text = text.split('---').join('');
  var lines = text.split('\n');
  var html = '';
  var inList = false;
  var firstSection = true;
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (line === '') continue;
    if (line.indexOf('## ') === 0) {
      if (inList) { html += '</ul>'; inList = false; }
      if (!firstSection) { html += '</div></div>'; }
      html += '<div class="section"><h2>' + line.substring(3) + '</h2><div class="section-content">';
      firstSection = false;
    } else if (line.indexOf('- ') === 0 && line.length > 2) {
      if (!inList) { html += '<ul class="rtl-list">'; inList = true; }
      html += '<li>' + formatLine(line.substring(2), srcMap) + '</li>';
    } else {
      if (inList) { html += '</ul>'; inList = false; }
      html += '<p>' + formatLine(line, srcMap) + '</p>';
    }
  }
  if (inList) html += '</ul>';
  if (!firstSection) html += '</div></div>';
  return html;
}

var formattedContent = formatContent(analysis, sourceMap);

var citationsHtml = '';
if (allSources.length > 0) {
  var citList = '';
  for (var i = 0; i < allSources.length; i++) {
    var source = allSources[i];
    var sourceName = source.name || getSourceName(source.url || '');
    var sourceUrl = source.url || '';
    var sourceTitle = source.title || '';
    var citNum = source.index;
    var isUsed = usedCitations[citNum] ? ' cite-used' : '';
    citList += '<div class="cite-item' + isUsed + '"><span class="cite-num">[' + citNum + ']</span><span class="cite-source">' + sourceName + '</span>';
    if (sourceTitle) {
      citList += '<span class="cite-title">' + sourceTitle + '</span>';
    }
    if (sourceUrl) {
      citList += '<a href="' + sourceUrl + '" target="_blank">' + sourceUrl + '</a>';
    }
    citList += '</div>';
  }
  citationsHtml = '<div class="section references"><h2>المراجع والمصادر</h2><div class="cite-list">' + citList + '</div></div>';
}

var htmlReport = '<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>' + reportTitle + '</title><style>@import url(https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700&display=swap);*{box-sizing:border-box}body{font-family:Tajawal,Segoe UI,Tahoma,sans-serif;direction:rtl;text-align:right;line-height:2;padding:20px;max-width:1000px;margin:0 auto;background:#f0f4f8;color:#1a202c}.container{background:white;padding:50px;border-radius:16px;box-shadow:0 4px 25px rgba(0,0,0,0.08)}.header{background:linear-gradient(135deg,#0d2137,#1a4a7a);color:white;padding:40px;text-align:center;border-radius:16px 16px 0 0;margin:-50px -50px 40px;position:relative}.header::after{content:"";position:absolute;bottom:0;right:0;left:0;height:4px;background:linear-gradient(90deg,#c9a227,#f4d03f,#c9a227)}.header h1{margin:0 0 12px;font-size:28px;font-weight:700}.header .subtitle{font-size:16px;opacity:0.95;margin-bottom:8px}.header .date{font-size:15px;opacity:0.9;margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,0.2)}.section{margin-bottom:30px;padding:25px 30px;background:linear-gradient(135deg,#fafbfc,#f1f5f9);border-radius:12px;border-right:6px solid #1a4a7a}.section h2{color:#0d2137;margin:0 0 20px;font-size:22px;font-weight:700;border-bottom:3px solid #e2e8f0;padding-bottom:12px;position:relative}.section h2::after{content:"";position:absolute;bottom:-3px;right:0;width:80px;height:3px;background:#c9a227}.section-content{color:#2d3748;font-size:16px;line-height:2.1}.section-content p{margin:0 0 12px;text-align:justify}.section-content strong{color:#1a4a7a;font-weight:700}.cite-link{color:#2563eb;font-size:13px;font-weight:600;text-decoration:none;vertical-align:super;margin:0 2px;background:#e0e7ff;padding:1px 4px;border-radius:3px}.cite-link:hover{text-decoration:underline;background:#c7d2fe}.rtl-list{margin:12px 0;padding:0;list-style:none}.rtl-list li{position:relative;padding-right:20px;margin-bottom:10px}.rtl-list li::before{content:"■";position:absolute;right:0;top:0;color:#c9a227;font-size:10px}.references{background:linear-gradient(135deg,#f0fdf4,#dcfce7);border-right-color:#16a34a}.references h2{color:#166534}.references h2::after{background:#16a34a}.cite-list{display:flex;flex-direction:column;gap:10px}.cite-item{display:flex;align-items:flex-start;gap:10px;padding:12px 15px;background:white;border-radius:8px;flex-wrap:wrap}.cite-item.cite-used{border-right:3px solid #16a34a}.cite-num{color:#166534;font-weight:700;flex-shrink:0;min-width:30px}.cite-source{color:#0d2137;font-weight:700;background:#e0e7ff;padding:2px 8px;border-radius:4px;flex-shrink:0}.cite-title{color:#4a5568;font-size:14px;flex-basis:100%;margin-top:5px;font-style:italic}.cite-item a{color:#1d4ed8;word-break:break-all;text-decoration:none;font-size:13px;flex:1;min-width:200px}.cite-item a:hover{text-decoration:underline}.footer{text-align:center;padding:25px;color:#64748b;font-size:14px;border-top:2px solid #e2e8f0;margin-top:30px}.footer .org{font-weight:700;color:#1a4a7a;font-size:15px;margin-bottom:6px}.footer .disclaimer{font-size:12px;margin-top:10px;color:#94a3b8;padding:8px 12px;background:#f8fafc;border-radius:6px;border:1px dashed #cbd5e1;display:inline-block}@media print{body{background:white;padding:0}.container{box-shadow:none}}</style></head><body><div class="container"><div class="header"><h1>التقرير اليومي للرصد الجنائي والأمني</h1><div class="subtitle">إدارة الاستخبارات الجنائية</div><div class="subtitle">حكومة الإمارات العربية المتحدة</div><div class="date">' + dateArabic + '</div></div>' + formattedContent + citationsHtml + '<div class="footer"><div class="org">نظام الرصد الجنائي الذكي</div><div>حكومة الإمارات العربية المتحدة</div><div class="disclaimer">سري - للاستخدام الرسمي فقط</div></div></div></body></html>';

return {
  json: {
    report_html: htmlReport,
    report_title: reportTitle,
    file_name: 'criminal_intelligence_report_' + dateEnglish + '.html',
    date: dateEnglish,
    sources_count: allSources.length,
    citations_used: Object.keys(usedCitations).length
  },
  binary: {
    report_file: {
      data: Buffer.from(htmlReport).toString('base64'),
      mimeType: 'text/html',
      fileName: 'criminal_intelligence_report_' + dateEnglish + '.html'
    }
  }
};
